const $=s=>document.querySelector(s),services=[['1-on-1 personal training','A session that starts with your goals, not a one-size-fits-all routine.','$80 / session'],['Online coaching','A practical plan and consistent check-ins, wherever you train.','$149 / month'],['Nutrition habits','Build sustainable everyday habits with a supportive approach.','$99 / consultation'],['Small-group training','Good energy and shared accountability in a welcoming group.','$25 / session'],['Corporate wellness','Movement and habits that fit the working day.','$300 / workshop']];
const programs=[['12-week transformation','Habits','12 weeks · $399–$599','Weekly sessions, habit check-ins and a sustainable routine.'],['Build your strong','Strength','10 weeks · $299–$499','Progressive strength fundamentals with weekly plan reviews.'],['Sustainable weight goals','Habits','12 weeks · $399–$599','Movement, consistency and supportive nutrition habits.'],['Ready for game day','Performance','8 weeks · $349–$549','Sport-focused strength and conditioning, adjusted to experience.'],['Return to movement','Habits','8 weeks · $249–$449','Gentle postpartum movement planning after individual medical clearance.']];
function modal(t,d){$('#dt').textContent=t;$('#dd').textContent=d;$('#dialog').showModal()}
$('#servicesgrid').innerHTML=services.map((s,i)=>`<article class="service"><span class="small">0${i+1} / COACHING</span><h3>${s[0]}</h3><p>${s[1]}</p><b>From ${s[2]}</b><button data-service="${i}">Learn more →</button></article>`).join('');
function render(){const list=programs.map((p,i)=>({p,i})).filter(({p})=>$('#focus').value==='All goals'||p[1]===$('#focus').value);$('#programgrid').innerHTML=list.map(({p,i})=>`<article class="program"><span>↗ ${p[1].toUpperCase()}</span><h3>${p[0]}</h3><p>${p[2]}<br>${p[3]}</p><button data-program="${i}">Explore program →</button></article>`).join('')}
document.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.service!==undefined){const s=services[+b.dataset.service];modal(s[0],s[1]+' Starting from '+s[2]+'. This fictional service is an inquiry preview; use the consultation form to explore the local booking interaction.')}if(b.dataset.program!==undefined){const p=programs[+b.dataset.program];modal(p[0],p[2]+'. '+p[3]+' Sample program only. No training contract or payment is created.')}if(b.dataset.social)modal(b.dataset.social+' preview','No real social account is represented. Educational videos and posts would appear here in a live coach portfolio.')};
$('#focus').onchange=render;
const stories=[['“I stopped chasing a perfect week and started building a routine I could actually keep.”','JAMIE · 12-week sample journey','Inconsistent routine','Three weekly sessions'],['“Feeling capable in the gym changed how I felt everywhere else.”','MORGAN · 10-week sample journey','Unsure where to start','Confident fundamentals'],['“The plan worked around my workday, not the other way around.”','CASEY · 8-week sample journey','Busy schedule','Regular movement breaks']];let story=0;
function renderStory(){const s=stories[story];$('#quote').textContent=s[0];$('#person').textContent=s[1];$('#before').textContent=s[2];$('#after').textContent=s[3]}$('#next').onclick=()=>{story=(story+1)%3;renderStory()};$('#prev').onclick=()=>{story=(story+2)%3;renderStory()};
$('#resourceform').onsubmit=e=>{e.preventDefault();const text='7-day sample movement plan\nEducational, not personalized advice. Choose comfortable movement and consult a qualified professional if needed.\nDay 1: Easy walk.\nDay 2: Gentle mobility.\nDay 3: Rest or comfortable walk.\nDay 4: Light bodyweight practice.\nDay 5: Easy movement break.\nDay 6: Activity you enjoy.\nDay 7: Rest and reflect.\nStop activity if uncomfortable.';const link=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));link.href=url;link.download='seven-day-movement-plan.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#resourcestatus').textContent='Your sample text plan downloaded. No email was sent.'};
const today=new Date(),date=new Date(today.getTime()-today.getTimezoneOffset()*60000).toISOString().slice(0,10);$('#date').min=date;$('#date').value=date;let slot='';
function slots(){slot='';$('#slots').innerHTML=['09:00 AM','12:30 PM','05:00 PM'].map(t=>`<button type="button" data-slot="${t}">${t}</button>`).join('');document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{slot=b.dataset.slot;document.querySelectorAll('[data-slot]').forEach(x=>x.classList.toggle('selected',x===b))})}$('#date').onchange=slots;$('#bookform').onsubmit=e=>{e.preventDefault();if(!slot){$('#bookingstatus').textContent='Choose a sample time slot.';return}$('#bookingstatus').textContent='Local preview: '+$('#session').value+' on '+$('#date').value+' at '+slot+'. No booking created or email sent.'};render();renderStory();slots();
